-- =============================================================================
-- 0074_platform_exercise_library.sql — общая библиотека упражнений платформы
--
-- Зачем. Экран /app/library читает упражнения платформы (center_id is null) и
-- упражнения центра, но платформенных строк не заводил никто: ни миграция, ни
-- seed, ни экран (save_exercise пишет только в свой центр, триггер
-- exercise_library_center_required не даёт роли authenticated завести строку
-- без центра — 0040 Р3, «платформенное упражнение заводится только
-- миграцией»). Библиотека у всех центров, включая prod, была пустой.
--
-- Что это. Только данные, схема не меняется: 90 упражнений в девяти областях
-- (артикуляционная гимнастика, звукопроизношение по этапам, дыхание и голос,
-- мелкая моторика, фонематический слух, слоговая структура, лексика и
-- грамматика, связная речь, чтение и письмо). Набор собран по анализу
-- русскоязычных методических источников и обзоров доказательной базы —
-- docs/Research/exercise-library-analysis.md: что и как считалось, откуда
-- взяты частоты, чего в данных нет. Тексты инструкций написаны заново
-- (перефраз, не выдержки из источников).
--
-- Решения.
--   Р1. Вставка идемпотентна: строка платформы с тем же названием (без учёта
--       регистра; уникальность даёт exercise_library_center_title_uniq,
--       nulls not distinct) не дублируется, а уже существующая — не
--       перезаписывается: правка текста после мержа делается следующей
--       миграцией, а не молчаливой заменой.
--   Р2. stage_code — текст, не ссылка: платформенная строка не может ссылаться
--       на goal_stages центра (Р7, 0036). Используются семь кодов, которые
--       заводит seed_goal_stages: setting, isolated, syllables, words,
--       phrases, speech, differentiation. Артикуляционная гимнастика, дыхание,
--       моторика, фонематика, лексика и чтение этапа звукопроизношения не
--       имеют — stage_code пуст.
--   Р3. Теги — словарь вводит эта миграция (экран его не расшифровывает; теги
--       — свободный текст, ни RPC, ни триггер их не проверяют, то есть это
--       подсказка, а не запрет): «дом» — годится для домашнего задания;
--       «кабинет» — основной формат в кабинете, дома — по назначению
--       специалиста; «только специалист» — этап целиком за специалистом;
--       «зеркало», «карточки», «с материалами», «без материалов» — оснащение;
--       «популярное» — упражнение назвали не менее 7 из 16 прочитанных
--       источников по артикуляционной гимнастике (частота — ориентир, а не
--       статистика по логопедам).
--   Р4. Доказательность. Для неречевых оромоторных упражнений (артикуляционная
--       гимнастика без звука, дыхательные «выдувания») систематические обзоры
--       не находят пользы при обычных нарушениях звукопроизношения; оправданы
--       они при подтверждённой моторной патологии (дизартрия, слабость,
--       ограниченная подвижность). Это сказано в первом упражнении области
--       («общие правила») и в анализе; библиотека не утверждает, что
--       гимнастика обязательна.
--   Р5. Методическое содержание — не решение схемы: набор должен прочитать
--       действующий логопед ДО мержа (миграции идут по порядку, и любая
--       следующая схемная уедет на prod вместе с этой). Поправки после мержа —
--       только update текста или is_active = false, НИКОГДА deleted_at: политика
--       чтения прячет удалённую строку, у родителя в выданном ДЗ пропало бы
--       название, а homework_exercises_check_center_refs отбил бы снятие
--       такого упражнения из задания.
--   Р7. Безопасность (ревью): пошаговые приёмы, которые родитель не должен
--       выполнять (механическая помощь шпателем/пальцем, постановка звука от
--       опорных звуков), в набор не вносятся вовсе — библиотеку читает и
--       родитель (политика 0036 пускает parent, названия нужны в ДЗ), а тег
--       «только специалист» ничего не запрещает. Нет открытого огня и
--       воздушных шаров (риск асфиксии латексом). Мелкие предметы — под
--       присмотром. Выдувания подаются как «плавный выдох», а не как средство
--       постановки звука. Занятия на звук дома — по назначению специалиста.
--   Р8. Выгрузка центра (export_center_table фильтрует center_id =
--       current_center()) не содержит платформенных строк, а
--       homework_exercises.exercise_id на них ссылаться может — раньше платформа
--       была пуста. Записано как долг, здесь не чинится.
--   Р6. media_url не заполняется: ссылки на чужие материалы (авторские права,
--       живучесть адресов) — дело центра.
--
-- Аудит: apply_audit пишет по строке на вставку (user_id null); шум разовый.
-- =============================================================================

insert into public.exercise_library
  (center_id, area, sound, stage_code, title, instructions, age_from, age_to, tags)
select null::uuid, v.area, v.sound, v.stage_code, v.title, v.instructions, v.age_from, v.age_to, v.tags
  from (values
  ('артикуляционная гимнастика', null, null, 'Артикуляционная гимнастика: общие правила', 'Занимайтесь перед зеркалом 5–10 минут в день, по 1–2 новых упражнения за раз, от простого к сложному. Каждое движение выполняйте медленно, следите, чтобы двигался только язык или губы, а не челюсть. Гимнастика без звука подготавливает подвижность органов артикуляции; для обычных нарушений произношения её пользу исследования не подтверждают, поэтому основное время отдавайте работе над самим звуком, а гимнастику используйте там, где есть слабость или ограниченная подвижность (например, при дизартрии).', 3, 7, array['дом', 'зеркало', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Лошадка', 'Рот приоткрыт, широкий язык присасывается к нёбу и с щелчком отрывается; нижняя челюсть остаётся неподвижной. Сначала медленно и громко, затем быстрее. Развивает подъём языка, используется в подготовке к Р, Л, Ш. Выполнять без боли; при дискомфорте остановиться и показать ребёнка специалисту.', 4, 7, array['дом', 'зеркало', 'популярное', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Лопатка', 'Рот открыт, широкий расслабленный язык лежит на нижней губе, края не загнуты и не напряжены. Держать 5–15 секунд, без напряжения. Основа для свистящих и шипящих, помогает расслабить язык.', 3, 7, array['дом', 'зеркало', 'популярное', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Грибок', 'Широкий язык целиком присасывается к нёбу, рот широко открыт, подъязычная связка натянута. Держать до 5–10 секунд, не тянуть нижнюю челюсть вниз. Используется в подготовке к Ш, Ж, Р, Л. Выполнять без боли; при дискомфорте остановиться и показать ребёнка специалисту.', 4, 7, array['дом', 'зеркало', 'популярное', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Трубочка (хоботок)', 'Губы вытянуты вперёд, как хоботок слона, зубы сомкнуты. Держать до счёта пять, повторить 5–7 раз. Готовит губы к Ш, Ж, Щ, Ч, О, У и к переходу между улыбкой и трубочкой.', 2, 7, array['дом', 'зеркало', 'популярное', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Улыбка и заборчик', 'Губы растянуты в спокойной улыбке, зубы сомкнуты и видны («заборчик»). Держать до счёта пять, следить за симметрией уголков рта. Затем чередовать с трубочкой: улыбка — трубочка, 5–7 раз.', 2, 7, array['дом', 'зеркало', 'популярное', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Качели', 'Рот открыт, язык поочерёдно тянется к носу и к подбородку (или к верхним и нижним зубам), челюсть неподвижна. Повторять 5–10 раз, следить за плавностью движения.', 3, 7, array['дом', 'зеркало', 'популярное', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Часики', 'Рот приоткрыт, узкий язык поочерёдно тянется к уголкам рта, как маятник. Губы и челюсть не участвуют. По 5–10 движений в каждую сторону, темп медленный, затем быстрее.', 3, 7, array['дом', 'зеркало', 'популярное', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Вкусное варенье', 'Широким языком «слизывают варенье» с верхней губы движением сверху вниз, края языка достают до уголков рта. Нижняя челюсть не помогает. 5–10 раз; готовит язык к Ш, Ж, Л, Р.', 4, 7, array['дом', 'зеркало', 'популярное', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Чистим зубки', 'Кончик языка проходит по внутренней стороне верхних зубов из стороны в сторону, затем нижних. Двигается только язык, губы улыбаются. По 8–10 движений в каждую сторону; развивает точность контакта, полезно перед С и Р.', 3, 7, array['дом', 'зеркало', 'популярное', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Чашечка', 'Из положения «лопатка» боковые края и кончик языка поднимаются вверх, не касаясь зубов, получается ложка без заострённого кончика. Держать 5–10 секунд. Готовит язык к Ш, Ж, Ч, Щ.', 4, 7, array['дом', 'зеркало', 'популярное', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Маляр', 'Рот широко открыт, кончик языка «красит» нёбо от зубов вглубь, пока нет неприятных ощущений, и назад. Темп медленный, челюсть неподвижна, 5–10 движений. Готовит язык к Р и Л.', 4, 7, array['дом', 'зеркало', 'популярное', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Фокус', 'Широкий язык лежит на верхней губе, на кончик носа кладут ватку, на выдохе струя воздуха идёт по центру языка и сдувает её вверх. Повторить 2–5 раз, следить, чтобы щёки не раздувались. Помогает получить направленную воздушную струю для Ш, Ж и Р.', 4, 7, array['дом', 'зеркало', 'популярное', 'с материалами']::text[]),
  ('артикуляционная гимнастика', null, null, 'Барабанщик', 'Кончик языка часто стучит по бугоркам за верхними зубами со звуком «д-д-д», рот открыт, челюсть неподвижна. Темп постепенно растёт, серия 10–15 секунд, 4–5 серий. Подготовка вибрации для Р.', 4, 7, array['дом', 'зеркало', 'популярное', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Бублик', 'Губы округлены и слегка вытянуты, между ними видны сомкнутые зубы. Держать до счёта пять, следить за симметрией. Вариант перехода: улыбка — бублик — трубочка.', 2, 7, array['дом', 'зеркало', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Горка', 'Кончик языка упирается в нижние зубы, спинка выгнута вверх, боковые края прижаты к верхним коренным зубам. Держать 10–15 секунд. Готовит язык к С, З, Ц.', 4, 7, array['дом', 'зеркало', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Иголочка', 'Узкий напряжённый язык вытянут вперёд, как жало. Держать 5–10 секунд, затем расслабить. Учит удерживать кончик языка узким; полезно для С и Р.', 4, 7, array['дом', 'зеркало', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Индюк (болтушка)', 'Широкий язык скользит по верхней губе вперёд и назад с голосом «бл-бл-бл», темп растёт. По 5–6 циклов. Развивает подвижность языка для Р и Л.', 4, 7, array['дом', 'зеркало', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Хомячки (щёки)', 'Надуть обе щёки и удержать воздух, затем втянуть щёки внутрь («голодный хомячок»). Чередовать 5–7 раз. Упражнение для щёк, включать его по назначению специалиста.', 3, 7, array['дом', 'зеркало', 'без материалов']::text[]),
  ('дыхание и голос', null, null, 'Ветерок (воздушная струя)', 'Ребёнок дует узкой струёй воздуха; взрослый подносит ладонь или бумажную полоску и показывает, идёт ли струя по центру. 3–5 выдохов подряд, затем пауза; при головокружении остановиться. Ощущение направленной струи используют при работе над свистящими и шипящими по назначению специалиста; сам по себе приём произношение не исправляет.', 3, 7, array['дом', 'зеркало', 'свистящие', 'шипящие']::text[]),
  ('звукопроизношение', null, 'isolated', 'Песенки звуков', 'Изолированный звук в игровой форме: змея, комар, жук, поезд. Играть в «кто дольше» и «чья песенка чище» перед зеркалом. Взрослый показывает образец раньше ребёнка, чтобы не закреплять ошибку. Дома — по назначению специалиста, когда звук уже поставлен.', 3, 7, array['дом', 'зеркало', 'без материалов']::text[]),
  ('звукопроизношение', null, 'syllables', 'Слоговые ряды (прямые, обратные, интервокальные)', 'Отрабатываем звук в слогах по порядку: прямые (са-со-су), обратные (ас-ос-ус), между гласными (аса), со стечением (ста, спа). Для смычных и аффрикат начинают с обратных слогов. Менять ударение: са-СА-са. Дома — по назначению специалиста, когда звук уже поставлен.', 4, 7, array['дом', 'карточки']::text[]),
  ('звукопроизношение', null, 'words', 'Картинки на позиции звука', 'Для каждой позиции (начало, середина, конец слова) готовят 20–30 картинок; за занятие берут 10–16 слов и повторяют каждое 4–5 раз, растягивая нужный звук. Слова с конфликтными звуками (Р рядом с Л, С рядом с Ш) заранее убирают. Дома — по назначению специалиста, когда звук уже поставлен.', 4, 7, array['дом', 'карточки']::text[]),
  ('звукопроизношение', null, 'words', 'Слова вокруг нас', 'Дети по очереди называют предметы со звуком по комнате или теме («зимние слова на С»), можно с мячом. Взрослый иногда нарочно ошибается, ребёнок ловит ошибку. Дома — по назначению специалиста, когда звук уже поставлен.', 4, 7, array['дом', 'без материалов']::text[]),
  ('звукопроизношение', null, 'words', 'Чего не стало?', 'На столе 6–7 картинок со звуком. Ребёнок закрывает глаза, взрослый убирает или меняет картинки местами, ребёнок называет, что изменилось, полным словом со звуком. Дома — по назначению специалиста, когда звук уже поставлен.', 4, 7, array['дом', 'карточки']::text[]),
  ('звукопроизношение', null, 'phrases', 'Предложение по двум картинкам', 'Ребёнок объединяет две картинки в одно предложение со словами на отрабатываемый звук. Начинать с короткой фразы, затем усложнять. Дома — по назначению специалиста, когда звук уже поставлен.', 5, 7, array['дом', 'карточки']::text[]),
  ('звукопроизношение', null, 'phrases', 'Найди ошибку (нелепицы)', 'Взрослый произносит фразу с нелепостью («пол стоит на столе»), ребёнок находит ошибку и исправляет её, чётко проговаривая слова со звуком. Дома — по назначению специалиста, когда звук уже поставлен.', 5, 7, array['дом', 'карточки']::text[]),
  ('звукопроизношение', null, 'phrases', 'Чистоговорки и потешки', 'Слоговый ритм («ас-ас-ас — у нас дома ананас») и короткие стихи на закрепляемый звук. Сначала произносить медленно с подсказкой, потом увеличивать темп и убирать подсказку. Дома — по назначению специалиста, когда звук уже поставлен.', 4, 7, array['дом', 'без материалов']::text[]),
  ('звукопроизношение', null, 'speech', 'Расскажи, что было в садике', 'Взрослый задаёт наводящие вопросы о прошедшем дне и спокойно повторяет слово правильно («маШШШинку»), не заставляя переговаривать. Дома — по назначению специалиста, когда звук уже поставлен.', 5, 7, array['дом', 'без материалов']::text[]),
  ('звукопроизношение', null, 'differentiation', 'Незнайка спрашивает', 'Игрушка-Незнайка спрашивает, что значит близкое по звучанию слово («мишка» и «миска», «каска» и «кашка»); ребёнок объясняет и находит нужную картинку. По сути минимальные пары.', 5, 9, array['кабинет', 'дом', 'карточки']::text[]),
  ('звукопроизношение', null, 'differentiation', 'Мяч вверх — мяч вниз (С — Ш)', 'Мяч показывает положение языка: С — мяч отбивают о пол, Ш — поднимают вверх. Ребёнок слушает слова или звуки и показывает мячом, какой звук слышит; затем произносит сам.', 4, 7, array['кабинет', 'дом', 'с материалами']::text[]),
  ('звукопроизношение', null, 'differentiation', 'Подними карточку (пары звуков)', 'Два звука — две карточки. Взрослый произносит слоги или слова, ребёнок поднимает карточку нужного звука. Пары: С–Ш, Ж–З, Р–Л, Ч–Щ.', 5, 9, array['кабинет', 'дом', 'карточки']::text[]),
  ('звукопроизношение', null, null, 'Домашнее занятие на автоматизацию: структура', 'Ежедневно 5–15 минут, лучше в спокойное время (не голодным и не уставшим). 1–2 минуты вход в игру, 10 минут основная часть, физкультминутка каждые 3–5 минут, 1–2 минуты похвала. Взрослый показывает образец раньше ребёнка, не читает список слов ребёнку вместо занятия и не переходит к словам, пока изолированный звук нечёткий.', 4, 9, array['дом']::text[]),
  ('дыхание и голос', null, null, 'Озвученный выдох', 'Ребёнок набирает воздух носом и тянет один звук (гласную, ф, ш, с, ж) или слоговую цепочку, не добирая воздух. Сначала звук, потом 2–3 слога, потом слова и фраза за один выдох. Считать, сколько слогов удалось. Цель — плавный длинный выдох в речи, а не «сила лёгких». 3–5 выдохов подряд, затем пауза; при головокружении остановиться.', 3, 7, array['дом', 'без материалов']::text[]),
  ('дыхание и голос', null, null, 'Сдувание ваты и снежинок', 'На ладонь кладут ватку или бумажную снежинку, ребёнок сдувает её на длинном выдохе (вата — под присмотром взрослого). Играть в снегопад или листопад. Вдох через нос, плечи не поднимать, щёки не надувать. 3–5 выдохов подряд, затем пауза; при головокружении остановиться.', 3, 7, array['дом', 'с материалами']::text[]),
  ('дыхание и голос', null, null, 'Вертушка', 'Ребёнок дует на лопасти игрушки, чтобы она вращалась. Силу регулировать словами «слабее — сильнее», выдох плавный. Игрушка-вертушка. 3–5 выдохов подряд, затем пауза; при головокружении остановиться.', 3, 7, array['дом', 'с материалами']::text[]),
  ('дыхание и голос', null, null, 'Футбол (ватный шарик в ворота)', 'Ватный шарик нужно «забить» в ворота из кубиков воздушной струёй. Струя направленная, щёки не надувать. 3–5 выдохов подряд, затем пауза; при головокружении остановиться.', 3, 7, array['дом', 'с материалами']::text[]),
  ('дыхание и голос', null, null, 'Трубочка в стакан с водой', 'Соломинка (5–6 мм) в стакане с водой: ребёнок выдувает «бульки» и «шторм». Следить, чтобы ребёнок не пил воду, не грыз трубочку и выдыхал ртом, а не носом. 3–5 выдохов подряд, затем пауза; при головокружении остановиться.', 4, 7, array['дом', 'с материалами']::text[]),
  ('дыхание и голос', null, null, 'Громко — тихо — шёпот', 'Без крика: один звук или счёт произносят ступенями: беззвучная артикуляция → шёпот → обычный голос → громко и обратно. Можно привязать к сюжету: гудок паровоза приближается и удаляется.', 3, 7, array['дом', 'без материалов']::text[]),
  ('дыхание и голос', null, null, 'Высота голоса', 'Одну фразу произносят низко, средне и высоко, изображая медведей или пароходы разного размера. Рука взрослого идёт вверх и вниз, помогая ребёнку следовать высоте голоса.', 3, 7, array['дом', 'без материалов']::text[]),
  ('мелкая моторика', null, null, 'Пальчиковые потешки', 'Текст сопровождается движениями пальцев: «Ладушки», «Сорока-белобока», «Коза рогатая». Сначала правая рука, потом левая, потом обе, по 3–5 повторов, 2–3 раза в день по несколько минут. Не требовать одновременно и движения, и текст, пока не освоено первое.', 3, 7, array['дом', 'без материалов']::text[]),
  ('мелкая моторика', null, null, 'Самомассаж кистей', 'Поглаживание, растирание и надавливание пальцев, шарик или мячик-ёжик в ладони, 2–5 минут. Разогреть ладони перед занятием; можно начинать или заканчивать им занятие.', 3, 9, array['дом', 'с материалами']::text[]),
  ('мелкая моторика', null, null, 'Карандаш между ладонями', 'Катать шестигранный карандаш между ладонями вверх и вниз. Мягко массирует кисти. Только под присмотром взрослого.', 4, 9, array['дом', 'с материалами']::text[]),
  ('мелкая моторика', null, null, 'Шнуровка, пуговицы, застёжки', 'Бытовые действия тренируют захват и точность: шнуровка, пуговицы, липучки, бантики. Успех приходит не с первого раза; мелкие предметы давать под присмотром взрослого.', 3, 7, array['дом', 'с материалами']::text[]),
  ('мелкая моторика', null, null, 'Мозаика, конструктор, пазлы', 'Готовые наборы для мелких захватов (мелкие детали — под присмотром взрослого); размер деталей подбирать по возрасту. Можно сочетать с речью: называть цвет и форму детали.', 3, 7, array['дом', 'с материалами']::text[]),
  ('мелкая моторика', null, null, 'Крупы и «сухой бассейн»', 'Руки погружают по запястье в миску с фасолью или гречкой, ищут спрятанные предметы, сортируют, рисуют на подносе с манкой. Только под присмотром: мелкие предметы.', 3, 6, array['дом', 'с материалами']::text[]),
  ('мелкая моторика', null, null, 'Фигурки пальцами', 'Показывать пальцами «зайчика», «козу», «очки», «замок», называя, какой палец что делает; затем разыгрывать сценки. Если трудно, взрослый придерживает лишние пальцы.', 4, 7, array['дом', 'без материалов']::text[]),
  ('мелкая моторика', null, null, 'Прищепки', 'Открывать и закрывать прищепки на ритм стишка; в связке с фонематикой ими отмечают звук или позицию звука в слове.', 3, 7, array['дом', 'с материалами']::text[]),
  ('мелкая моторика', null, null, 'Нанизывание бусин', 'Нанизывание бус на шнурок тренирует пинцетный захват. Начинать с крупных бусин, затем уменьшать размер; мелкие детали давать под присмотром взрослого.', 3, 7, array['дом', 'с материалами']::text[]),
  ('мелкая моторика', null, null, 'Лепка', 'Лепка из пластилина или теста: раскатать колбаску, шарик, соединить детали. Развивает силу пальцев; можно совмещать с названием предметов и признаков.', 3, 7, array['дом', 'с материалами']::text[]),
  ('фонематический слух', null, null, 'Поймай звук', 'Взрослый называет ряд звуков, слогов или слов, ребёнок хлопает или топает на заданный звук. Согласные произносить коротко, без «э». Начинать со звуков, затем слоги, затем слова.', 4, 7, array['дом', 'без материалов']::text[]),
  ('фонематический слух', null, null, 'Хлопни — топни', 'Пары слов: если звучат одинаково — хлопок, если по-разному — топ. Вариант: взрослый «ошибается» в названии предмета, ребёнок хлопает, услышав ошибку.', 4, 7, array['дом', 'без материалов']::text[]),
  ('фонематический слух', null, null, 'Светофор (правильно — неправильно)', 'Красный и зелёный кружки: ребёнок показывает зелёный, если слово названо правильно, красный — если с ошибкой. Тот же приём подходит для места звука: красная, жёлтая и зелёная зоны полоски.', 4, 7, array['дом', 'карточки']::text[]),
  ('фонематический слух', null, null, 'Что звучало?', 'Звучащие предметы (бубен, колокольчик, свистулька, баночка с крупой) прячут за ширмой, ребёнок узнаёт звук на слух. Число предметов растёт с 3 до 5.', 3, 7, array['дом', 'с материалами']::text[]),
  ('фонематический слух', null, null, 'Место звука в слове', 'Полоска из трёх клеток: начало, середина, конец. Ребёнок ставит фишку туда, где слышен звук. Сложнее всего слышать звук в середине слова, начинать с начала и конца.', 4, 7, array['дом', 'карточки']::text[]),
  ('фонематический слух', null, null, 'Первый и последний звук (цепочка слов)', 'Картинки соединяют так, чтобы первый звук следующей совпадал с последним звуком предыдущей: «мак — кот — топор». Играть с картинками на столе или «поездом».', 5, 7, array['дом', 'карточки']::text[]),
  ('фонематический слух', null, null, 'Придумай слово на звук', 'Ребёнок называет слова на заданный звук, ищет картинки со звуком, играет в «зоркий глаз» в комнате. Начинать с начала слова.', 4, 7, array['дом', 'без материалов']::text[]),
  ('фонематический слух', null, null, 'Живые звуки (модель слова)', 'Дети или фишки становятся звуками слова и выстраиваются по порядку, остальные угадывают слово. Так закрепляют звуковой анализ и синтез.', 5, 7, array['кабинет', 'карточки']::text[]),
  ('слоговая структура', null, null, 'Прохлопать слова по слогам', 'Слово делят на части хлопками, шагами или ударами в бубен; сначала вместе со взрослым, потом сам. Потом сравнить с картинкой-схемой, где столько кружков, сколько слогов.', 3, 7, array['дом', 'без материалов']::text[]),
  ('слоговая структура', null, null, 'Слоговые дорожки и поезд', 'Палец ребёнка «идёт» по дорожке на каждом слоге, вагоны поезда — слоги слова. Слова подбирают от простых (два открытых слога) к сложным (со стечением).', 4, 7, array['дом', 'карточки']::text[]),
  ('слоговая структура', null, null, 'Добавь слог, закончи слово', 'Взрослый бросает мяч и называет начало слова («ма-...»), ребёнок ловит и заканчивает («...ма»). Затем ребёнок добавляет слог к готовому слову: «Какое слово получилось?».', 4, 7, array['дом', 'без материалов']::text[]),
  ('слоговая структура', null, null, 'Повторюшки: слоговые ряды на слух', 'Взрослый называет ряд слогов (па-по-пу), ребёнок повторяет, затем находит «лишний». Ряды постепенно удлиняют, меняют порядок и ударение.', 4, 7, array['дом', 'без материалов']::text[]),
  ('лексика и грамматика', null, null, 'Назови ласково', 'Ребёнок превращает названия предметов в мягкие формы: дом — домик, мяч — мячик. Взрослый показывает предмет и его игрушечную копию. Начинают с одного суффикса, потом смешивают.', 4, 7, array['дом', 'карточки']::text[]),
  ('лексика и грамматика', null, null, 'Предлоги на предметах', 'Ребёнок кладёт игрушку в коробку, под неё, за неё и говорит, где она лежит. Сначала действие, потом слово. Сначала простые предлоги (в, на), позже под, за, из, перед; возраст освоения сверяйте со специалистом.', 3, 7, array['дом', 'с материалами']::text[]),
  ('лексика и грамматика', null, null, 'Один — много', 'Взрослый показывает один предмет, ребёнок называет несколько таких предметов: «один стул — много стульев». Отдельно тренируют слова с непредсказуемой формой (носок — носков).', 4, 7, array['дом', 'без материалов']::text[]),
  ('лексика и грамматика', null, null, 'Согласование: один, одна, одно', 'Картинки сортируют по родовым словам (мой — моя — моё), затем добавляют определения: красное яблоко, красная юбка.', 5, 7, array['дом', 'карточки']::text[]),
  ('лексика и грамматика', null, null, 'Счёт с существительными', 'Ребёнок считает матрёшки или яблоки и подбирает окончание: одно, два, пять. Ошибки вроде «семь яблоко» разбирают на примере, не ругая.', 5, 7, array['дом', 'карточки']::text[]),
  ('лексика и грамматика', null, null, 'Достроить предложение', 'Взрослый начинает фразу («Мы сделали кораблик, чтобы...»), ребёнок заканчивает. Постепенно вводят «если», «потому что».', 5, 7, array['дом', 'без материалов']::text[]),
  ('лексика и грамматика', null, null, 'Чей? Какой?', 'Ребёнок образует прилагательные от существительных: сок из яблок — яблочный, хвост лисы — лисий. Опора на картинки.', 5, 7, array['дом', 'карточки']::text[]),
  ('лексика и грамматика', null, null, 'Детёныши и профессии', 'Ребёнок называет малышей животных (у лисы — лисёнок) и людей по действию (кто чинит часы — часовщик). Проверяют суффиксы и род.', 4, 7, array['дом', 'карточки']::text[]),
  ('лексика и грамматика', null, null, 'Скажи наоборот', 'Взрослый называет слово, ребёнок отвечает противоположным: большой — маленький, горячий — холодный. Можно с мячом.', 4, 7, array['дом', 'без материалов']::text[]),
  ('связная речь', null, null, 'Рассказ по серии картинок', 'Ребёнок раскладывает 3–4 картинки по порядку и составляет связный рассказ с началом, серединой и концом. Дать опору на порядок: сначала, потом, в конце.', 4, 7, array['дом', 'карточки']::text[]),
  ('связная речь', null, null, 'Описание картины', 'Взрослый задаёт открытые вопросы («Что происходит? Какая погода?»), ребёнок складывает ответы в рассказ. Сначала образец взрослого, потом самостоятельно.', 3, 7, array['дом', 'карточки']::text[]),
  ('связная речь', null, null, 'Описание предмета по схеме', 'Ребёнок называет цвет, форму, размер, материал, части и то, что с предметом делают. Схему рисуют один раз и используют многократно.', 5, 7, array['дом', 'карточки']::text[]),
  ('связная речь', null, null, 'Пересказ', 'Взрослый читает короткий текст и обсуждает его, затем ребёнок пересказывает: сначала близко к тексту, потом выборочно, потом с творческими изменениями.', 5, 9, array['дом', 'без материалов']::text[]),
  ('связная речь', null, null, 'Рассказ по образцу', 'Взрослый даёт короткий образец и разбирает его («Как я начал? Что было дальше?»). Ребёнок повторяет структуру на новой картинке.', 4, 6, array['дом', 'карточки']::text[]),
  ('связная речь', null, null, 'Придумай продолжение', 'Одну картинку серии закрывают, ребёнок придумывает, что было до неё или после. Развивает воображение и причинно-следственные связи.', 5, 7, array['дом', 'карточки']::text[]),
  ('связная речь', null, null, 'Рассказ цепочкой', 'Каждый (ребёнок, родитель, брат) добавляет по одному предложению. Хорошо подходит тем, кому трудно сказать «сразу весь рассказ».', 4, 7, array['дом', 'без материалов']::text[]),
  ('связная речь', null, null, 'Расширение предложения', 'Из одной фразы строят связную цепочку: «Расцвёл цветок» → «Расцвёл красный цветок» → «Он чудесно пахнет». Каждый следующий ход добавляет признак или действие.', 5, 7, array['дом', 'без материалов']::text[]),
  ('чтение и письмо', null, null, 'Слоговые таблицы «назови — найди — прочти»', 'Взрослый называет слог, ребёнок быстро показывает его в таблице и читает; таблицы часто меняют. Ошибка — разбирать слог по буквам: слог читают целиком.', 6, 9, array['кабинет', 'дом', 'карточки']::text[]),
  ('чтение и письмо', null, null, 'Звуковой анализ слова (звуковая дорожка)', 'Ребёнок делит слово на слоги и звуки хлопками или фишками, называет число гласных и позицию звука. Работа идёт от слов к фразам.', 5, 8, array['кабинет', 'карточки']::text[]),
  ('чтение и письмо', null, null, 'Различение фонем: слог, слово, предложение', 'Пары б–п, с–ш и других предъявляют сначала в слогах, потом в словах и предложениях. Порядок: услышал, произнёс, отличил, записал.', 7, 9, array['кабинет', 'карточки']::text[]),
  ('чтение и письмо', null, null, 'Конструирование букв', 'Буквы собирают из палочек и картона, лепят из пластилина, рисуют пальцем на ладони или в манке. Цель — устойчивый образ буквы.', 5, 8, array['дом', 'с материалами']::text[]),
  ('чтение и письмо', null, null, 'Буквы в осложнённых условиях', 'Ребёнок находит буквы, перечёркнутые, наложенные друг на друга или спрятанные среди других. Тренирует зрительное узнавание похожих букв.', 6, 8, array['кабинет', 'карточки']::text[]),
  ('чтение и письмо', null, null, 'Найди пару (зрительная память)', 'Игры «Что изменилось?» и «Найди пару» на карточках. Начинают с малого числа картинок и постепенно добавляют.', 5, 8, array['дом', 'карточки']::text[]),
  ('чтение и письмо', null, null, 'Лево — право (ориентировка)', 'Игры с предметами и листом бумаги, затем с буквами: где лево, где право, что до и после. Готовит к различению похожих по написанию букв.', 5, 8, array['дом', 'с материалами']::text[]),
  ('чтение и письмо', null, null, 'Лесенка слов', 'Список слов усложняется от короткого к длинному (ам — ама — мама — мамаша). Читают вниз и вверх; слоги помечают цветом или чертой.', 6, 9, array['кабинет', 'дом', 'карточки']::text[]),
  ('звукопроизношение', null, 'setting', 'Постановка звука: работа специалиста', 'Постановку звука ведёт специалист по своей методике: по подражанию, от опорных звуков, при необходимости с механической помощью. Пошаговые приёмы в библиотеку намеренно не вносятся: родителю их выполнять нельзя. На этом этапе домашнее задание обычно ограничивается артикуляционной гимнастикой и воздушной струёй по назначению специалиста.', 5, 7, array['кабинет', 'только специалист']::text[]),
  ('дыхание и голос', null, null, 'Дыхательные упражнения: общие правила', 'Занимайтесь в проветренной комнате, не сразу после еды. 3–5 выдохов подряд, затем пауза; при головокружении остановитесь. Вдох носом, плечи не поднимать, щёки не надувать. Дыхательные «выдувания» сами по себе произношение звуков не исправляют, обзоры такой пользы не подтверждают; их цель — плавный длинный выдох в речи и удобный голос. Мелкие предметы (вата, бумага) давать под присмотром.', 3, 7, array['дом', 'без материалов']::text[]),
  ('артикуляционная гимнастика', null, null, 'Змейка', 'Узкий язык вытягивают вперёд и втягивают обратно, как змея. Повторить 5–7 раз, следить за симметрией и узостью языка. Выполнять без боли.', 4, 7, array['дом', 'зеркало', 'без материалов']::text[])
  ) as v(area, sound, stage_code, title, instructions, age_from, age_to, tags)
 where not exists (
   select 1 from public.exercise_library e
    where e.center_id is null and e.deleted_at is null and lower(e.title) = lower(v.title)
 );
